def make_typed_dict(*, required_fields=None, optional_fields=None) ->type:
    if required_fields is None:
        required_fields = {}
    if optional_fields is None:
        optional_fields = {}

    # Create the TypedDict class with the actual fields
    all_fields = {}
    all_fields.update(required_fields)
    all_fields.update(optional_fields)

    # Create the main TypedDict with proper structure
    typed_dict_class = TypedDict(
        DUMMY_TYPED_DICT_NAME,
        all_fields,
        total=len(optional_fields) == 0
    )

    return typed_dict_class
